package cn.mop.persistence;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.security.MessageDigest;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Actual restricted project PG; synthetic job/receipt descriptions always roll back, no store calls. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresAssetExportSchemaIntegrationTest {
    static HikariDataSource pool;Connection c;String actor;long permission;
    static final String TENANT="55000000-0000-4000-8000-000000000001";
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(2);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);}
    @BeforeEach void begin()throws Exception{c=pool.getConnection();c.setAutoCommit(false);actor=scalar("SELECT user_id::text FROM public.mop_membership WHERE tenant_id='"+TENANT+"' AND role_code='padmin' AND active ORDER BY user_id LIMIT 1");permission=Long.parseLong(scalar("SELECT permission_version::text FROM public.mop_membership WHERE tenant_id='"+TENANT+"' AND user_id='"+actor+"'"));}
    @AfterEach void rollback()throws Exception{if(c!=null){c.rollback();c.close();}}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    void sql(String value)throws SQLException{try(var s=c.createStatement()){s.execute(value);}}
    String scalar(String value)throws SQLException{try(var s=c.createStatement();var r=s.executeQuery(value)){assertTrue(r.next());return r.getString(1);}}
    @FunctionalInterface interface Action{void run()throws Exception;}
    void rejected(String state,Action action)throws Exception{var sp=c.setSavepoint();var error=assertThrows(SQLException.class,action::run);assertEquals(state,error.getSQLState());c.rollback(sp);c.releaseSavepoint(sp);}
    String job()throws Exception{String id=UUID.randomUUID().toString();byte[] command=new Command(new Access(UUID.fromString(TENANT),UUID.fromString(actor),permission,"padmin",true),new Filters(null,null,null,null)).canonicalBytes();try(var s=c.prepareStatement("INSERT INTO public.mop_asset_export_job(id,tenant_id,created_by,permission_version,accepted_role,command_bytes,trace_id) VALUES (?::uuid,?::uuid,?::uuid,?,'padmin',?,?)")){s.setString(1,id);s.setString(2,TENANT);s.setString(3,actor);s.setLong(4,permission);s.setBytes(5,command);s.setString(6,UUID.randomUUID().toString());s.executeUpdate();}return id;}
    String where(String id){return " WHERE id='"+id+"'";}
    void change(String id,String fields)throws SQLException{sql("UPDATE public.mop_asset_export_job SET version=version+1,updated_at=statement_timestamp(),"+fields+where(id));}
    void claim(String id,String duration)throws SQLException{change(id,"state=CASE WHEN file_bytes IS NULL THEN 'RUNNING' ELSE 'RECONCILING_STORAGE' END,fencing_token=fencing_token+1,lease_owner='schema-only',lease_started_at=statement_timestamp()::timestamptz(3),lease_until=statement_timestamp()::timestamptz(3)+interval '"+duration+"'");}
    void prepare(String id)throws SQLException{change(id,"file_bytes=decode('01020304','hex'),selection_sha256='"+"a".repeat(64)+"',row_count=2,generated_at=statement_timestamp()");}
    void unknown(String id)throws SQLException{change(id,"state='RECONCILING_STORAGE'");}
    void failed(String id,String reason)throws SQLException{change(id,"state='FAILED',error_code='"+reason+"'");}
    void stored(String id)throws SQLException{change(id,"state='SUCCEEDED',object_id=gen_random_uuid(),stored_at=statement_timestamp()");}
    @Test void runtimeStructureAclAndGuardBodiesMatchReviewedResource()throws Exception{AssetExportSchemaVerifier.verify(c);assertEquals("mop_test_runtime",scalar("SELECT current_user"));}
    @Test void canonicalAcceptanceHasDatabaseHashAndNoAttempt()throws Exception{String id=job();assertEquals("QUEUED|0|0",scalar("SELECT state||'|'||version||'|'||fencing_token FROM public.mop_asset_export_job"+where(id)));try(var s=c.createStatement();var r=s.executeQuery("SELECT command_bytes,input_sha256 FROM public.mop_asset_export_job"+where(id))){r.next();assertEquals(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(r.getBytes(1))),r.getString(2));}assertEquals("0",scalar("SELECT count(*) FROM public.mop_asset_export_attempt WHERE job_id='"+id+"'"));}
    @Test void invalidScopeRoleVersionAndPayloadBoundsReject()throws Exception{String prefix="INSERT INTO public.mop_asset_export_job(id,tenant_id,created_by,permission_version,accepted_role,command_bytes,trace_id) VALUES (gen_random_uuid(),'"+TENANT+"','"+actor+"',";rejected("23514",()->sql(prefix+"0,'padmin','x'::bytea,'schema')"));rejected("23514",()->sql(prefix+"1,'viewer','x'::bytea,'schema')"));rejected("23514",()->sql(prefix+"1,'padmin',''::bytea,'schema')"));rejected("23514",()->sql(prefix+"1,'padmin',decode(repeat('00',4097),'hex'),'schema')"));rejected("23503",()->sql("INSERT INTO public.mop_asset_export_job(id,tenant_id,created_by,permission_version,accepted_role,command_bytes,trace_id) VALUES (gen_random_uuid(),gen_random_uuid(),'"+actor+"',1,'padmin','x'::bytea,'schema')"));}
    @Test void insertCannotSkipQueueAndVersionZero()throws Exception{for(String state:List.of("RUNNING","RECONCILING_STORAGE","SUCCEEDED","FAILED"))rejected("23514",()->sql("INSERT INTO public.mop_asset_export_job(id,tenant_id,created_by,permission_version,accepted_role,command_bytes,trace_id,state) VALUES (gen_random_uuid(),'"+TENANT+"','"+actor+"',1,'padmin','x'::bytea,'schema','"+state+"')"));}
    @Test void claimAtomicallyAppendsAttemptAndCannotStealActiveLease()throws Exception{String id=job();claim(id,"30 seconds");assertEquals("RUNNING|1|1",scalar("SELECT state||'|'||version||'|'||fencing_token FROM public.mop_asset_export_job"+where(id)));assertEquals("1",scalar("SELECT count(*) FROM public.mop_asset_export_attempt WHERE job_id='"+id+"'"));rejected("23514",()->claim(id,"30 seconds"));assertEquals("1",scalar("SELECT count(*) FROM public.mop_asset_export_attempt WHERE job_id='"+id+"'"));}
    @Test void preparedBytesSizeAndHashAreFrozenAcrossTransitions()throws Exception{String id=job();claim(id,"30 seconds");prepare(id);String hash=scalar("SELECT file_sha256 FROM public.mop_asset_export_job"+where(id));assertEquals(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(new byte[]{1,2,3,4})),hash);assertEquals("4",scalar("SELECT file_size::text FROM public.mop_asset_export_job"+where(id)));rejected("23514",()->change(id,"file_bytes=decode('05','hex')"));rejected("23514",()->change(id,"row_count=3"));rejected("23514",()->change(id,"file_bytes=NULL,selection_sha256=NULL,row_count=NULL,generated_at=NULL"));unknown(id);assertEquals(hash,scalar("SELECT file_sha256 FROM public.mop_asset_export_job"+where(id)));}
    @Test void invalidPreparationAndLeaseBoundariesReject()throws Exception{String id=job();rejected("23514",()->claim(id,"11 minutes"));claim(id,"30 seconds");rejected("23514",()->change(id,"file_bytes=decode('01','hex'),selection_sha256='"+"a".repeat(64)+"',row_count=1001,generated_at=statement_timestamp()"));rejected("23514",()->change(id,"file_bytes=decode('01','hex')"));rejected("23514",()->change(id,"state='RECONCILING_STORAGE'"));rejected("23514",()->change(id,"fencing_token=1001"));}
    @Test void expiredPreparedLeaseCannotCompleteAndReclaimForcesReconciliation()throws Exception{String id=job();claim(id,"500 milliseconds");prepare(id);sql("SELECT pg_sleep(0.55)");rejected("23514",()->stored(id));claim(id,"30 seconds");assertEquals("RECONCILING_STORAGE|2",scalar("SELECT state||'|'||fencing_token FROM public.mop_asset_export_job"+where(id)));assertEquals("2",scalar("SELECT count(*) FROM public.mop_asset_export_attempt WHERE job_id='"+id+"'"));}
    @Test void expiredUnpreparedLeaseCanRestartWithoutInventingArtifact()throws Exception{String id=job();claim(id,"10 milliseconds");sql("SELECT pg_sleep(0.03)");claim(id,"30 seconds");assertEquals("RUNNING|2",scalar("SELECT state||'|'||fencing_token FROM public.mop_asset_export_job"+where(id)));assertEquals("true",scalar("SELECT (file_bytes IS NULL)::text FROM public.mop_asset_export_job"+where(id)));}
    @Test void confirmedAbsenceDescriptionRetainsExactPreparedBytes()throws Exception{String id=job();claim(id,"30 seconds");prepare(id);unknown(id);change(id,"state='RUNNING'");assertEquals("01020304",scalar("SELECT encode(file_bytes,'hex') FROM public.mop_asset_export_job"+where(id)));rejected("23514",()->change(id,"state='RUNNING'"));}
    @Test void receiptDescriptionRequiresPriorPreparationAndTerminalCannotChange()throws Exception{String id=job();claim(id,"30 seconds");rejected("23514",()->stored(id));rejected("23514",()->change(id,"file_bytes=decode('01','hex'),selection_sha256='"+"a".repeat(64)+"',row_count=1,generated_at=statement_timestamp(),state='SUCCEEDED',object_id=gen_random_uuid(),stored_at=statement_timestamp()"));prepare(id);stored(id);assertEquals("SUCCEEDED",scalar("SELECT state FROM public.mop_asset_export_job"+where(id)));rejected("23514",()->change(id,"object_id=gen_random_uuid()"));rejected("23514",()->claim(id,"30 seconds"));}
    @Test void queuedAndExpiredAuthorizationDenialRetainOriginalFacts()throws Exception{String queued=job();failed(queued,"AUTHORIZATION_CHANGED");assertEquals("FAILED|0",scalar("SELECT state||'|'||fencing_token FROM public.mop_asset_export_job"+where(queued)));String id=job();claim(id,"500 milliseconds");prepare(id);sql("SELECT pg_sleep(0.55)");failed(id,"AUTHORIZATION_CHANGED");assertEquals("FAILED|01020304",scalar("SELECT state||'|'||encode(file_bytes,'hex') FROM public.mop_asset_export_job"+where(id)));}
    @Test void unknownStorageCannotBeHiddenBehindAnUnrelatedFailure()throws Exception{String id=job();claim(id,"30 seconds");prepare(id);unknown(id);rejected("23514",()->failed(id,"SOURCE_UNAVAILABLE"));failed(id,"CONFIRMED_STORAGE_REJECTION");assertEquals("FAILED",scalar("SELECT state FROM public.mop_asset_export_job"+where(id)));}
    @Test void leaseVersionAndHistoryCannotBeEditedWithoutClaim()throws Exception{String id=job();claim(id,"30 seconds");rejected("23514",()->sql("UPDATE public.mop_asset_export_job SET lease_until=lease_until+interval '1 second'"+where(id)));rejected("23514",()->change(id,"lease_owner='other'"));rejected("23514",()->change(id,"fencing_token=fencing_token-1"));rejected("23514",()->sql("UPDATE public.mop_asset_export_job SET version=version+1,updated_at=clock_timestamp()+interval '1 hour'"+where(id)));}
    @Test void forgedAttemptCannotInsertAnotherFenceOrForeignLease()throws Exception{String id=job();claim(id,"30 seconds");rejected("23514",()->sql("INSERT INTO public.mop_asset_export_attempt SELECT tenant_id,id,2,lease_owner,lease_started_at,lease_until FROM public.mop_asset_export_job"+where(id)));rejected("23514",()->sql("INSERT INTO public.mop_asset_export_attempt SELECT tenant_id,id,1,'forged',lease_started_at,lease_until FROM public.mop_asset_export_job"+where(id)));rejected("23505",()->sql("INSERT INTO public.mop_asset_export_attempt SELECT tenant_id,id,1,lease_owner,lease_started_at,lease_until FROM public.mop_asset_export_job"+where(id)));}
    @Test void runtimeCannotRewriteAcceptanceAttemptsOrDeleteData()throws Exception{for(String query:List.of("UPDATE public.mop_asset_export_job SET command_bytes='x'::bytea WHERE false","UPDATE public.mop_asset_export_job SET accepted_role='msp' WHERE false","UPDATE public.mop_asset_export_job SET created_by=gen_random_uuid() WHERE false","UPDATE public.mop_asset_export_attempt SET lease_owner='forged' WHERE false","DELETE FROM public.mop_asset_export_job WHERE false","DELETE FROM public.mop_asset_export_attempt WHERE false","TRUNCATE public.mop_asset_export_job"))rejected("42501",()->sql(query));}
}
